import { expect, expectStatus, test, uniqueName } from "../../fixtures";

test("search and the status filter apply together", { tag: "@LIF-14" }, async ({ apiAs, factory }) => {
  // Arrange: two vendors sharing one unique word, one draft and one in review
  const word = uniqueName("Lifecycle").replace(/\s+/g, "");
  const draft = await factory.vendor({ name: `${word} Draft Supply` });
  const review = await factory.vendorInReview({ name: `${word} Review Supply` });

  // Act: list with the shared word as the search and status in_review
  const member = await apiAs("member");
  const response = await member.get("/api/vendors", {
    params: { q: word, status: "in_review" },
  });

  // Assert: exactly the vendor in review, and the total is 1
  const page = await expectStatus<{ items: { id: string; name: string; status: string }[]; total: number }>(response, 200);
  expect(page.total).toBe(1);
  expect(page.items.map((v) => v.id)).toEqual([review.vendor.id]);
  expect(page.items[0].status).toBe("in_review");
  expect(page.items.map((v) => v.id)).not.toContain(draft.id);
});
